// Word list access. Data comes from data/words.js (window.N3_WORDS), generated by tools/build-data.js
// from data/words-*.json — or, if that did not exist at build time, from the SAMPLE list in
// app/data/sample/words-sample.json (window.N3_WORDS_META.source === 'sample').
(function () {
  'use strict';
  const N3 = window.N3;
  const raw = Array.isArray(window.N3_WORDS) ? window.N3_WORDS : [];

  N3.META = window.N3_WORDS_META || { source: 'missing', count: 0 };
  N3.WORDS = raw
    .filter(w => w && w.id && w.word && w.reading && w.meaning && Number.isFinite(Number(w.unit)))
    .map((w, i) => Object.assign({}, w, { unit: Number(w.unit), _i: i }));
  N3.BY_ID = Object.fromEntries(N3.WORDS.map(w => [w.id, w]));
  N3.UNITS = [...new Set(N3.WORDS.map(w => w.unit))].sort((a, b) => a - b);
  N3.unitWords = u => N3.WORDS.filter(w => w.unit === u);

  N3.isUnitOpen = u => N3.hasAccess() || u <= N3.FREE_UNITS;
  N3.openWords = () => N3.WORDS.filter(w => N3.isUnitOpen(w.unit));

  N3.POS_LABEL = {
    noun: 'noun', verb: 'verb', 'na-adjective': 'na-adjective', 'i-adjective': 'i-adjective',
    adverb: 'adverb', expression: 'expression',
  };

  // Example sentence with the target word located. Returns null if the word does not occur in
  // dictionary form (e.g. a conjugated verb), in which case fill-in questions skip the word.
  N3.locateInExample = w => {
    const ex = w.example || '';
    const i = ex.indexOf(w.word);
    if (i < 0) return null;
    return { before: ex.slice(0, i), hit: w.word, after: ex.slice(i + w.word.length) };
  };

  N3.exampleHtml = w => {
    const loc = N3.locateInExample(w);
    if (!loc) return N3.esc(w.example || '');
    return `${N3.esc(loc.before)}<mark>${N3.esc(loc.hit)}</mark>${N3.esc(loc.after)}`;
  };

  N3.ruby = w => (w.word === w.reading ? N3.esc(w.word) : `<ruby>${N3.esc(w.word)}<rt>${N3.esc(w.reading)}</rt></ruby>`);

  // Word of the day: stable for a calendar day, drawn from the units the learner can open.
  N3.wordOfDay = () => {
    const pool = N3.openWords();
    if (!pool.length) return null;
    return pool[N3.hash('wotd:' + N3.today()) % pool.length];
  };
})();
